pageStyle:
.kpn-blog-leading-p {
    text-align: center;
    font-size: 1.5em;
}

.blog-post h3 {
    font-size: 2em;
}

.blog-post .author-name {
    font-weight: 600;
    font-size: 1.15em;
}

.blog-post .leading-image {
    width: 100%;
    border-radius: 10px;
}

.blog-post  .author-portrait {
    width: 80px;
    margin-right: 10px;
    margin-top: 25px;
}

.blog-post  .author-portrait img {
    width: 60px;
    border-radius: 30px;
}
